  startedAt: number
  endedAt?: number
  tools: number
  files: string[]
  agents: number
  tokens?: number
  cacheRead?: number
}

declare module 'claude-code' {
  interface PluginState {
    'agent-arcade': {
      agents: Record<string, AgentNode>
      feed: FeedEntry[]
